#!/usr/bin/env bash
# step82 — fix enqueue ON CONFLICT for the PARTIAL idempotency index (was
# throwing and being swallowed, so nothing ever queued). Overwrites the two
# enqueue sites, seeds a whatsapp.test template, and queues one real test
# message to the latest verified account so the worker delivers it now.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step82-$TS
mkdir -p "$BAK/routes" "$BAK/lib"
cp "$APP/routes/whatsapp.js" "$BAK/routes/whatsapp.js"
cp "$APP/lib/wanotify.js" "$BAK/lib/wanotify.js"
restore(){ echo "!! rollback"; cp "$BAK/routes/whatsapp.js" "$APP/routes/whatsapp.js"; cp "$BAK/lib/wanotify.js" "$APP/lib/wanotify.js"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> overwrite fixed enqueue sites"
base64 -d > "$APP/routes/whatsapp.js" <<'B64'

B64
base64 -d > "$APP/lib/wanotify.js" <<'B64'

B64
node --check "$APP/routes/whatsapp.js"; node --check "$APP/lib/wanotify.js"; echo "   syntax OK"

echo "==> seed test template + queue one test message (validates ON CONFLICT too)"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
(async()=>{
  await p.query("INSERT INTO wa_templates(key,body) VALUES('whatsapp.test','🔔 Test from {{site_name}}: your WhatsApp notifications are working. (Ref: {{customer_reference}})') ON CONFLICT(key) DO NOTHING");
  const lk = (await p.query("SELECT l.customer_id, l.whatsapp_identity_id, c.ref_code FROM customer_whatsapp_links l JOIN customers c ON c.id=l.customer_id WHERE l.status='ACTIVE' ORDER BY l.id DESC LIMIT 1")).rows[0];
  if(!lk){ console.log('   no verified account yet — skipping test enqueue'); await p.end(); return; }
  const idem = 'test-'+Date.now();
  await p.query("INSERT INTO wa_notifications(customer_id,destination_identity_id,template_key,vars,idempotency_key) VALUES($1,$2,'whatsapp.test',$3,$4) ON CONFLICT(idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING",
    [lk.customer_id, lk.whatsapp_identity_id, JSON.stringify({ site_name:'Galaxy Subz × Zayron', customer_reference: lk.ref_code||'' }), idem]);
  console.log('   queued test message for customer #'+lk.customer_id);
  await p.end();
})().catch(e=>{ console.error('ENQUEUE FAIL: '+e.message); process.exit(1); });
NODE

echo "==> restart + let worker deliver"; pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
sleep 12
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
(async()=>{
  const q = (await p.query("SELECT status, count(*)::int n FROM wa_notifications GROUP BY status ORDER BY status")).rows;
  console.log('   outbox: ' + (q.map(r=>r.status+'='+r.n).join(' ') || '(empty)'));
  const last = (await p.query("SELECT template_key, status, destination_phone, last_error FROM wa_notifications ORDER BY id DESC LIMIT 3")).rows;
  last.forEach(r=>console.log('    - '+r.template_key+' -> '+r.status+(r.destination_phone?(' to '+r.destination_phone):'')+(r.last_error?(' ('+r.last_error+')'):'')));
  await p.end();
})().catch(e=>{ console.error(e.message); p.end(); });
NODE
trap - ERR
echo "==> step82 OK — enqueue fixed. A SENT row = message delivered; check your WhatsApp."
